// The approval lane's store (docs/design/round7/studio/APPROVAL-LANE.md; main's go, 2026-11-10; round 8 dc-r8-selection-
// before-generation, layer 3). A generated Stagecraft spec reaches a child only when it was approved OFFLINE:
//   1. generated by a Foundry spec call (scripts/approve-generate.mjs; main runs it, the key is main's)
//   2. passed today's predicate checks and a local render at p360, p412 and l1366 (scripts/approve-check.mjs)
//   3. passed a rubric pass by a separate Claude judge that did not write it (the verdict, the judge's prompt and the
//      rendered images' hashes are kept)
//   4. written here, in git: data/studio-approved/<topicId>/<id>.json — the commit IS the approval.
// The runtime never calls a judge: the tray gate (server/forge3/tray-gate.js) shows a generated spec only when its hash is
// in this store, at a size its render passed; anything else is refused exactly as before.
//
// An approved piece carries what it is FOR — { topic, skill, misconceptionId, beat } — and a `because`: it is chosen only for
// a child who holds that mix-up; any other child gets the script's own board.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
export const STORE_DIR = path.join(REPO, "data/studio-approved");
export const JUDGED_SIZES = Object.freeze(["p360", "p412", "l1366"]);
/** main 2026-11-10: a piece is judged where it can be PLAYED — p412 and l1366; at p360 every Studio v2 world is refused (its twin
 *  is a word card), so a record stores p360 false. */
export const APPROVAL_SIZES = Object.freeze(["p412", "l1366"]);

/** The four pilots' first targets: one generated visual each, aimed at one named mix-up of the topic's kit. */
export const PILOT_TARGETS = Object.freeze([
  // (main 2026-11-10, after the retry judge: each `how` in the engine's own terms)
  { topicId: "c4-maths-ch05-t01", archetype: "slice-at@1", misconceptionId: "c4-maths-ch05-t01-m-unequal-parts",
    how: "marks false on every wave (marks draw the equal cut points: the child must judge equal size herself); every wave's sub agrees with its own items (a wave of {parts: 4} says chaar, never teen); one count per wave; no sub states the rule (never that the pieces must be the same size): subs say only what to do; plain Roman Hinglish" },
  { topicId: "c5-maths-ch02-t01", archetype: "catch-on-line@1", misconceptionId: "c5-maths-ch02-t01-m-count-marks",
    how: "ticks is the number of EQUAL GAPS from 0 to 1 (ticks 4 draws 3 marks). Set every wave's ticks to its fractions' denominator (thirds: ticks 3) and scaffoldTicks equal to ticks; every item lands on a mark; no title or sub says where an item goes (never middle, half, pehla or any mark); subs say only what to do; Roman Hinglish only" },
  // (catch-on-line's pods hold ONE value — two labels in a pod must be equal: the mix-up is shown by catching unit fractions one
  // at a time on one line, never by pairing two to compare; the first two calls paired 1/4 with 1/8 and fell back)
  { topicId: "c5-maths-ch02-t02", archetype: "catch-on-line@1", misconceptionId: "c5-maths-ch02-t02-m-bigger-denominator",
    how: "catch unit fractions one per item on ONE 0 to 1 line; ticks a common multiple of every denominator on that line (1/2, 1/4, 1/8: ticks 8; 1/3, 1/6: ticks 6) so each lands on a tick; 1/8 lands nearest 0; no title or sub names where an item goes or says a bigger bottom number makes a smaller piece: subs say only what to do" },
  { topicId: "c6-maths-ch06-t01", archetype: "area-claim@1", misconceptionId: "c6-maths-ch06-t01-m-area-perimeter",
    how: "every string plain class-6 Hinglish in Roman script: no stake, claim, plot, sq or units in English. The goal reads '<area> <n> <sq> <units>' and '<perimeter> <n> <units>', so set sq to varg and units to ikai (area 40 varg ikai); coach like Grid par khet banao; claim like BAN GAYA" },
]);

/**
 * main 2026-11-11 (regenerate, never rescue): an engine's own `how`, for every target on that engine — the rules its
 * judges found broken, in the engine's terms. A target's own `how` (PILOT_TARGETS) is used instead when it has one.
 */
export const ENGINE_HOW = Object.freeze({
  "catch-on-line@1": "ticks is the number of EQUAL GAPS from 0 to 1; set each wave's ticks (and scaffoldTicks) to a common multiple of every denominator on that line so each item lands on a tick; one fraction per item; no title or sub names where an item goes",
  "slice-at@1": "marks false on every wave (marks draw the cut points: the child judges equal size herself); every wave's sub agrees with its own items; no sub states the rule",
  "area-claim@1": "every string plain Roman Hinglish: no stake, claim, plot, sq or units in English; sq varg, units ikai (area 40 varg ikai)",
});
/**
 * A regeneration target for a scripted topic: the topic's catalogue game engine, aimed at the first misconception its
 * script's checks target (the first remediation beat, as the pilots were). → { topicId, archetype, misconceptionId, how? }
 * or null (no script, no game, or no targeted check).
 */
export function deriveTarget(topicId) {
  const pilot = PILOT_TARGETS.find((t) => t.topicId === topicId);
  if (pilot) return pilot;
  const j = scriptOf(topicId);
  let archetype = null;
  try { archetype = JSON.parse(fs.readFileSync(path.join(REPO, "data/studio-catalogue/topics", `${topicId}.json`), "utf8")).game?.archetype ?? null; } catch { archetype = null; }
  let misconceptionId = null;
  for (const sk of j?.skills ?? []) { for (const c of sk.checks ?? []) if (c?.targets) { misconceptionId = c.targets; break; } if (misconceptionId) break; }
  if (!j || !archetype || !misconceptionId) return null;
  return { topicId, archetype, misconceptionId, ...(ENGINE_HOW[archetype] ? { how: ENGINE_HOW[archetype] } : {}) };
}

/** The canonical JSON of a value (keys sorted): two specs that say the same thing hash the same. */
const canon = (v) => (Array.isArray(v) ? v.map(canon) : v && typeof v === "object" ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, canon(v[k])])) : v);
/** A spec's identity: sha256 of its archetype and canonical spec, 32 hex. */
export const specHash = (archetype, spec) => createHash("sha256").update(JSON.stringify({ a: String(archetype ?? ""), s: canon(spec ?? null) })).digest("hex").slice(0, 32);
export const fileHash = (file) => createHash("sha256").update(fs.readFileSync(file)).digest("hex");

/**
 * Where a piece aimed at `misconceptionId` sits in the topic's script: the remediation that fires for that mix-up (Brain's
 * scriptBeat.beatId `rem:<misconceptionId>`, the id the seam matches), after the first scripted check that targets it
 * (`<skillId>:<checkId>`). → { skillId, beat, when, check } or null.
 */
/** A topic's script: live (data/lesson-scripts) or staged (data/lesson-scripts-staged); null when it has none. */
function scriptOf(topicId) {
  for (const d of ["data/lesson-scripts", "data/lesson-scripts-staged"]) {
    try { return JSON.parse(fs.readFileSync(path.join(REPO, d, `${topicId}.json`), "utf8")); } catch { /* next */ }
  }
  return null;
}
export function beatFor(topicId, misconceptionId) {
  try {
    const j = scriptOf(topicId);
    if (!j) return null;
    for (const [i, sk] of (j.skills ?? []).entries()) {
      const skillId = sk.id ?? `${topicId}-s${i + 1}`;
      for (const c of sk.checks ?? []) if (c?.targets === misconceptionId && c.id) return { skillId, beat: `rem:${misconceptionId}`, when: "remediation", check: `${skillId}:${c.id}` };
    }
  } catch { /* no script */ }
  return null;
}

/**
 * What one generation attempt ends in — exactly one of: a candidate, or refused with its reason (main 2026-11-10: c4 made two
 * attempts both logged ok, and neither a candidate nor a refused file was written — an ok result whose content checks failed
 * fell between the two). → { kind: "candidate" } | { kind: "refused", why }.
 */
/** Romanised Hindi number words a content check reads as English (main 2026-11-10: "Teen hisse" failed content_safety_2 three
 *  times, "teen" read as the English word): a string carrying one should write the number in digits. → the words found. */
// (only the number words that are ALSO English words a content check reads as sensitive: "teen". "do", "char", "das" are
// ordinary English or harmless and would warn on every English explainer)
const NUMBER_WORDS = ["teen"];
export function numberWords(text) { const t = String(text ?? "").toLowerCase(); return NUMBER_WORDS.filter((w) => new RegExp(`(^|[^a-z])${w}([^a-z]|$)`).test(t)); }
/** The plain-words reason for a content refusal that a number word explains. */
export function numberWordHint(findings) {
  const hits = (findings ?? []).filter((f) => f.text && numberWords(f.text).length);
  return hits.length ? `; ${hits.map((f) => `the content check scored "${f.text}" (${f.key}) ${String(f.code).replace(/^content_safety_/, "")}; number words such as ${numberWords(f.text).map((w) => `'${w}'`).join(", ")} are the likely cause: write digits`).join("; ")}` : "";
}
export function attemptOutcome(r) {
  if (!r?.ok) return { kind: "refused", why: String(r?.why ?? "refused") };
  if (!r.payload?.spec) return { kind: "refused", why: "ok but no spec in the payload" };
  const failed = Object.entries(r.checks ?? {}).filter(([k, v]) => v === false || (v && typeof v === "object" && v.ok === false)).map(([k]) => k);
  if (failed.length) return { kind: "refused", why: `ok, but its checks failed: ${failed.join(", ")}${numberWordHint(r.checks?.contentFindings)}` };
  return { kind: "candidate" };
}

/**
 * main 2026-11-10 (c5-t02's approval withdrawn: 1/3 and 1/6 asked on a line of eighth ticks): every value a spec asks the
 * child to place lands EXACTLY on a tick of the line it is on — the board must be able to show its own answer. A predicate,
 * not an instruction. catch-on-line@1: a wave's `ticks` (and `scaffoldTicks`, when its scaffold is drawn) is the number of
 * equal gaps per unit; 0 or 1 draws no inner tick (an unmarked line holds any value). → { ok, why, misses: [...] }.
 */
export function valuesOnTicks(archetype, spec) {
  const misses = [];
  const val = (t) => { const m = /^\s*(\d+)\s+(\d+)\s*\/\s*(\d+)\s*$/.exec(String(t)) ?? null; if (m) return [Number(m[1]) * Number(m[3]) + Number(m[2]), Number(m[3])];
    const f = /^\s*(\d+)\s*\/\s*(\d+)\s*$/.exec(String(t)); if (f) return [Number(f[1]), Number(f[2])]; const n = /^\s*(\d+)\s*$/.exec(String(t)); return n ? [Number(n[1]), 1] : null; };
  if (archetype === "catch-on-line@1") {
    for (const [wi, w] of (spec?.waves ?? []).entries()) for (const it of w.items ?? []) for (const label of [].concat(it)) {
      const v = val(label);
      if (!v) continue;
      for (const [name, t] of [["ticks", w.ticks], ["scaffoldTicks", w.scaffoldTicks]]) {
        if (!(Number(t) > 1)) continue;
        if ((v[0] * t) % v[1] !== 0) misses.push(`wave ${wi + 1} "${w.title ?? ""}": ${label} is not on a tick of a line with ${name} ${t}`);
      }
    }
  }
  return { ok: misses.length === 0, why: misses.length ? misses.slice(0, 4).join("; ") : null, misses };
}

let memo = null, storeDir = STORE_DIR;
/** Tests only: read the store from another folder (null: back to data/studio-approved). */
export const _useStore = (dir) => { storeDir = dir ?? STORE_DIR; memo = null; never = null; };
/** Every approved record in the store (`approved: true`, the judge's pass, rendered legible at ≥ 1 judged size). Read once. */
export function loadApproved({ fresh = false, dir = storeDir } = {}) {
  if (memo && !fresh && dir === storeDir) return memo;
  const out = new Map();
  try {
    for (const t of fs.existsSync(dir) ? fs.readdirSync(dir) : []) {
      const d = path.join(dir, t);
      if (!fs.statSync(d).isDirectory()) continue;
      for (const f of fs.readdirSync(d).filter((x) => x.endsWith(".json") && x !== "manifest.json")) {
        try {
          const r = JSON.parse(fs.readFileSync(path.join(d, f), "utf8"));
          // (rendered at all three sizes; shown only at the sizes that passed — the tray gate reads byViewport per device)
          const okSizes = JUDGED_SIZES.some((s) => r?.render?.byViewport?.[s] === true);
          // (the hash must be the spec's own: a record edited by hand after approval is not approved)
          if (r?.approved === true && okSizes && r.judge?.verdict === "pass" && r.hash === specHash(r.archetype, r.spec)) out.set(r.hash, r);
        } catch { /* a broken record is not approved */ }
      }
    }
  } catch { /* no store */ }
  if (dir === storeDir) memo = out;
  return out;
}
export const _resetApproved = () => { memo = null; };

/** The tray gate's verdict for a generated spec: { byViewport, approved: id } when its hash is approved, else null. */
export function approvedVerdict(archetype, spec) {
  const r = loadApproved().get(specHash(archetype, spec));
  return r ? { pass: true, approved: r.id, byViewport: Object.fromEntries(JUDGED_SIZES.map((s) => [s, r.render.byViewport[s] === true])) } : null;
}

/** The approved pieces a round's reader may choose for a child who holds `misconceptionId` on `topicId` (with `because`). */
export function approvedFor({ topicId, misconceptionId }) {
  return [...loadApproved().values()].filter((r) => r.source !== "catalogue" && r.for?.topic === topicId && (!misconceptionId || r.for?.misconceptionId === misconceptionId))
    .map((r) => ({ id: r.id, hash: r.hash, archetype: r.archetype, spec: r.spec, for: r.for, because: r.because }));
}

/**
 * main's ruling (2026-11-10, after the 20-topic sample: 11 of 20 with a content fault, 2 wrong keys): a CATALOGUE piece reaches a
 * child only with a judged pass in this store, exactly like a generated piece. Switch STUDIO_CATALOGUE_JUDGED (default "on";
 * "off" serves the certified catalogue as before). An engine's own reviewed default spec is code, not catalogue content: it needs
 * no judgement. Reverse when a fresh random sample of 50 unjudged pieces passes the rubric at 95% or better.
 */
/**
 * main 2026-11-11: a piece refused by the predicates or by the judges is NEVER served, whatever any switch says
 * (data/studio-approved/never.json: { hashes: [{ hash, id, why }] }). The tray gate checks it before the store and before
 * STUDIO_CATALOGUE_JUDGED, so turning the judged rule off cannot bring a refused piece back.
 */
let never = null;
export function neverServe(archetype, spec) {
  if (!never) { try { never = new Set(JSON.parse(fs.readFileSync(path.join(storeDir, "never.json"), "utf8")).hashes.map((h) => h.hash)); } catch { never = new Set(); } }
  return never.has(specHash(archetype, spec));
}
export const _resetNever = () => { never = null; };
export const catalogueNeedsJudge = (env = process.env) => String(env.STUDIO_CATALOGUE_JUDGED ?? "on").trim().toLowerCase() !== "off";
let defaults = null, defaultStrings = {};
/**
 * 2026-11-11 (c5-t01 retry 5, a split verdict on "Run complete"): a Hinglish or Hindi spec that leaves an engine's own
 * English string of two or more words untranslated. A predicate, before any judge; single shared words ("Wave", "chain")
 * pass. → { ok, why, keys }.
 */
export function untranslatedStrings(archetype, spec) {
  const lang = String(spec?.lang ?? "en");
  if (lang === "en") return { ok: true, why: null, keys: [] };
  const d = defaultStrings[archetype] ?? {};
  const keys = Object.entries(spec?.strings ?? {}).filter(([k, v]) => typeof v === "string" && v === d[k] && v.trim().split(/\s+/).length >= 2).map(([k]) => k);
  return { ok: keys.length === 0, why: keys.length ? `English engine strings left in a ${lang} piece: ${keys.map((k) => `${k} "${spec.strings[k]}"`).join(", ")}` : null, keys };
}
/** Is `spec` the archetype's reviewed engine default (shared/studio-spec*.ts defaultSpec)? */
export async function _loadDefaults() {
  if (defaults) return defaults;
  const [{ ENGINE_SPECS }, { ENGINE_SPECS_EXT }] = await Promise.all([import("../../shared/studio-spec.ts"), import("../../shared/studio-spec-ext/index.ts")]);
  defaults = new Set(Object.entries({ ...ENGINE_SPECS, ...ENGINE_SPECS_EXT }).filter(([, d]) => d?.defaultSpec).map(([a, d]) => specHash(a, d.defaultSpec)));
  defaultStrings = Object.fromEntries(Object.entries({ ...ENGINE_SPECS, ...ENGINE_SPECS_EXT }).filter(([, d]) => d?.defaultSpec?.strings).map(([a, d]) => [a, d.defaultSpec.strings]));
  return defaults;
}
export const isReviewedDefault = (archetype, spec) => !!defaults && defaults.has(specHash(archetype, spec));
await _loadDefaults().catch(() => null);
